kernel_type:
∀ {p : GoLean.GoCore.Program} {ps : List GoLean.GoCore.Param} {roots : List GoLean.Loc} {fuel : Nat}
  {s : GoLean.GoCore.ExecState} {c : GoLean.GoCore.Machine.Config} {ch : GoLean.GoCore.Choices}
  {result : Except GoLean.Stop (GoLean.GoCore.ExecState × GoLean.GoCore.Choices)}
  {record : GoLean.GoCore.RecoveryRuntime.AbortRecord},
  GoLean.GoCore.RecoveryRuntime.Inv p ps roots s c →
    GoLean.GoCore.RecoveryRuntime.runConfigWithAbort fuel s c ch = (result, some record) →
      result = Except.error (GoLean.Stop.panic (GoLean.GoCore.Machine.stringPanicHead record.bytes record.recovered))
